const Dashboard = () => {
    return (
        <div className="dashboard">
            <h1>Trip Expense Dashboard</h1>
            <p>Welcome to the Trip Expense Splitter!</p>
            <div className="trip-summary">
                <h2>Trip Summary</h2>
                {/* Trip summary details will go here */}
            </div>
            <div className="expense-list">
                <h2>Expenses</h2>
                {/* List of expenses will go here */}
            </div>
            <div className="family-list">
                <h2>Participating Families</h2>
                {/* List of families will go here */}
            </div>
        </div>
    );
};

export default Dashboard;
